class Solution:
    def nearestDrone(self, drones, target):
        tx, ty = target
        bestD = float('inf')
        bestI = -1
        for i, (x, y, r) in enumerate(drones):
            d = abs(x - tx) + abs(y - ty)
            if d <= r and d < bestD:
                bestD = d
                bestI = i
        return bestI

